    strategy_name,
    strategy_version,
    strategy_run_id,
    strategy_run_ts,

    /***********************************************************************************************
    Output and archive timestamp metadata.

    These fields support traceability only.

    They are not strategy-comparison keys and should not be interpreted as business outcomes.
    ***********************************************************************************************/
    latest_output_created_ts,
    archive_inserted_ts,

    /***********************************************************************************************
    Archive and failed-counteroffer controls.

    These settings are important for explaining evidence capture and final counteroffer behavior.
    ***********************************************************************************************/
    archive_run_flag,
    strategy_archive_reset_mode,
    failed_counteroffer_resolution,

    /***********************************************************************************************
    Module 1 source mode.

    These fields document whether Module 2 consumed Module 1 latest-run output or an archived
    Module 1 scenario slice.
    ***********************************************************************************************/
    module1_input_source,
    module1_source_table_name,

    /***********************************************************************************************
    Module 1 lineage.

    These fields preserve upstream synthetic population and scenario context.
    ***********************************************************************************************/
    module1_model_version,
    module1_scenario_set_name,
    module1_scenario_name,
    population_id,
    anchor_date,

    /***********************************************************************************************
    Structural counts.
    ***********************************************************************************************/
    applications,
    distinct_application_id_count,
    duplicate_application_count,

    /***********************************************************************************************
    Final decision counts.
    ***********************************************************************************************/
    approval_count,
    counteroffer_count,
    manual_review_count,
